const p = $input.first().json.body || $input.first().json;
return { json: {
  userId: p.userId, sessionId: p.sessionId, source: p.source,
  message: p.message || p.enrichedMessage || '', originalMessage: p.originalMessage || p.message || '',
  persona: typeof p.persona === 'string' ? JSON.parse(p.persona) : (p.persona || {}),
  replyTarget: p.replyTarget, replyToken: p.replyToken,
  timestamp: p.timestamp || new Date().toISOString(),
